import {
  FileCode2,
  Braces,
  Palette,
  Atom,
  Hexagon,
  Server,
  Workflow,
} from "lucide-react";
import { skillGroups } from "@/lib/data";

const icons: Record<string, React.ComponentType<{ size?: number; strokeWidth?: number; style?: React.CSSProperties }>> = {
  JavaScript: Braces,
  HTML5: FileCode2,
  CSS3: Palette,
  "React.js": Atom,
  "Next.js": Hexagon,
  "Node.js": Server,
  "Express.js": Workflow,
};

export default function Skills() {
  return (
    <section
      id="skills"
      className="border-b"
      style={{ borderColor: "var(--border-soft)", background: "var(--surface)" }}
    >
      <div className="mx-auto max-w-6xl px-6 py-24 sm:px-10">
        <span
          className="font-display text-sm italic"
          style={{ color: "var(--sage)" }}
        >
          Skills
        </span>
        <h2 className="font-display mt-3 max-w-lg text-3xl leading-tight sm:text-4xl">
          The tools I reach for.
        </h2>

        <div className="mt-14 grid gap-10 sm:grid-cols-3">
          {skillGroups.map((group) => (
            <div key={group.category}>
              <h3
                className="text-xs tracking-wide"
                style={{ color: "var(--text-faint)" }}
              >
                {group.category}
              </h3>
              <div className="mt-5 flex flex-col gap-3">
                {group.items.map((item) => {
                  const Icon = icons[item];
                  return (
                    <div
                      key={item}
                      className="group flex items-center gap-3 rounded-xl p-3.5 transition-colors duration-300"
                      style={{
                        background: "var(--bg)",
                        border: "1px solid var(--border-soft)",
                      }}
                    >
                      <span
                        className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg"
                        style={{ background: "var(--surface-2)" }}
                      >
                        {Icon && (
                          <Icon size={17} strokeWidth={1.75} style={{ color: "var(--accent)" }} />
                        )}
                      </span>
                      <span className="text-[15px]" style={{ color: "var(--text)" }}>
                        {item}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
